{
  "category_edits": [
    {
      "category": "network_architecture",
      "rationale": "Halve each feed-forward intermediate width, bounded below by one, to reduce capacity and computation. Preserve causal attention, activation, dropout, residual paths and all other training behavior. Save the width in checkpoint state and metadata, and reconstruct it in the predictor.",
      "edits": [
        {
          "find": "class PointWiseFeedForward(nn.Module):
    def __init__(self, hidden_units: int, dropout_rate: float):
        super().__init__()
        self.conv1 = nn.Conv1d(hidden_units, hidden_units, kernel_size=1)
        self.dropout1 = nn.Dropout(dropout_rate)
        self.relu = nn.ReLU()
        self.conv2 = nn.Conv1d(hidden_units, hidden_units, kernel_size=1)",
          "replace": "class PointWiseFeedForward(nn.Module):
    def __init__(self, hidden_units: int, dropout_rate: float, ff_hidden_units: int):
        super().__init__()
        self.conv1 = nn.Conv1d(hidden_units, ff_hidden_units, kernel_size=1)
        self.dropout1 = nn.Dropout(dropout_rate)
        self.relu = nn.ReLU()
        self.conv2 = nn.Conv1d(ff_hidden_units, hidden_units, kernel_size=1)"
        },
        {
          "find": "                 num_heads: int = 1, dropout_rate: float = 0.5, maxlen: int = 128):
        super().__init__()
        self.hidden_units = hidden_units
        self.maxlen = maxlen
        self.itemnum = itemnum",
          "replace": "                 num_heads: int = 1, dropout_rate: float = 0.5, maxlen: int = 128,
                 ff_hidden_units: int | None = None):
        super().__init__()
        self.hidden_units = hidden_units
        self.maxlen = maxlen
        self.itemnum = itemnum
        ff_hidden_units = max(1, hidden_units // 2) if ff_hidden_units is None else ff_hidden_units
        self.register_buffer("ff_hidden_width", torch.tensor(ff_hidden_units, dtype=torch.long))"
        },
        {
          "find": "            self.forward_layers.append(PointWiseFeedForward(hidden_units, dropout_rate))",
          "replace": "            self.forward_layers.append(PointWiseFeedForward(hidden_units, dropout_rate, ff_hidden_units))"
        },
        {
          "find": "        dropout_rate=DROPOUT_RATE,
        maxlen=MAXLEN,
    ).to(device)",
          "replace": "        dropout_rate=DROPOUT_RATE,
        maxlen=MAXLEN,
        ff_hidden_units=max(1, HIDDEN_UNITS // 2),
    ).to(device)"
        },
        {
          "find": "            "hidden_units": HIDDEN_UNITS,
            "num_blocks": NUM_BLOCKS,",
          "replace": "            "hidden_units": HIDDEN_UNITS,
            "ff_hidden_units": int(model.ff_hidden_width.item()),
            "num_blocks": NUM_BLOCKS,"
        },
        {
          "find": "            dropout_rate=0.0,
            maxlen=meta["maxlen"],
        ).to(_device)",
          "replace": "            dropout_rate=0.0,
            maxlen=meta["maxlen"],
            ff_hidden_units=meta["ff_hidden_units"],
        ).to(_device)"
        }
      ]
    }
  ],
